import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"组件库落地（Phase 2 as-built）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/design/redesign-2026-10-16-组件库落地.md","filePath":"zh/design/redesign-2026-10-16-组件库落地.md"}'),r={name:"zh/design/redesign-2026-10-16-组件库落地.md"};function n(i,t,c,s,l,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="组件库落地-phase-2-as-built" tabindex="-1">组件库落地（Phase 2 as-built） <a class="header-anchor" href="#组件库落地-phase-2-as-built" aria-label="Permalink to &quot;组件库落地（Phase 2 as-built）&quot;">​</a></h1><blockquote><p>2026-10-16。redesign-plan §5 的组件库在仓内的实际落点。设计稿是外部输入，本文记录<strong>已落地的仓内事实</strong>： 令牌单源、组件工厂清单、收编面与未收编余量。词汇表与契约见 <code>redesign-2026-10-16-契约.md</code>（widget 侧）。</p></blockquote><h2 id="_1-令牌体系-单源与委托" tabindex="-1">1 令牌体系（单源与委托） <a class="header-anchor" href="#_1-令牌体系-单源与委托" aria-label="Permalink to &quot;1 令牌体系（单源与委托）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>单源</th><th>落点</th></tr></thead><tbody><tr><td>字号/圆角/间距</td><td><code>src/Beacon.App/Services/DesignTokens.cs</code></td><td>8 档字号 + 6 档圆角 + 间距刻度；App 侧 C# 面唯一来源</td></tr><tr><td>圆角（XAML 面）</td><td><code>src/Beacon.App/App.xaml</code> 资源镜像</td><td>WinUI 3 无 <code>x:Static</code>，XAML 只能走 <code>StaticResource</code>；<strong>C# 与 XAML 两处必须同步改</strong>（两侧均有同步警示注释）</td></tr><tr><td>色彩/状态色</td><td><code>UiPalette</code>（App）+ <code>PaletteResolver</code>/<code>HighContrastPalette</code>（Core）</td><td>组件工厂一律不持色，brush 由调用面解析后传入</td></tr><tr><td>基础前景/背景</td><td><code>ThemeColors</code>（App.Windows）</td><td>进度条轨道底色等经 <code>Opacity</code> 派生</td></tr><tr><td>动效</td><td><code>MotionEngine</code>（App）</td><td>时长/缓动单源，组件不内嵌动画常量</td></tr><tr><td>尺寸/DPI</td><td><code>DpiLayoutMath</code>（Core）</td><td>DIP→px 只在 Win32 边界换算一次（四窗同口径）</td></tr><tr><td>进度档位</td><td><code>ProgressTiers</code>（Core，0.8/0.98 阈值）</td><td>PinnedHost <code>BarFillColor</code> 委托，App 不再持有阈值</td></tr></tbody></table><p>值等价纪律：收编一律<strong>值零变化</strong>（CI S/O/Q/F5/G 像素断言锚定）；<code>3</code>（详情表行距、chip 顶底距）等 off-scale 字面量按原值收进组件并注释，不在收编顺带改视觉。</p><h2 id="_2-组件工厂清单-src-beacon-app-components" tabindex="-1">2 组件工厂清单（<code>src/Beacon.App/Components/</code>） <a class="header-anchor" href="#_2-组件工厂清单-src-beacon-app-components" aria-label="Permalink to &quot;2 组件工厂清单（`src/Beacon.App/Components/`）&quot;">​</a></h2><p>约定：<code>internal static class</code> 工厂；组件持排版/几何（走 DesignTokens），<strong>不持配色</strong>（brush 由调用面给）； 条件子元素一律命令式 <code>Add</code>（集合初始化器内 null 运行时炸）。</p><table tabindex="0"><thead><tr><th>工厂</th><th>件</th><th>采用面（仓内事实）</th></tr></thead><tbody><tr><td>ComponentText</td><td>Caption / Body</td><td>QuickPanel 状态行/事件行（a517594）</td></tr><tr><td>ComponentIcon</td><td>StatusDot</td><td>QuickPanel 行首灯</td></tr><tr><td>ComponentSurface</td><td>Card</td><td>词汇件（设置卡面同口径）</td></tr><tr><td>ComponentBadge</td><td>Count</td><td>词汇件</td></tr><tr><td>ComponentDivider</td><td>Horizontal</td><td>词汇件</td></tr><tr><td>ComponentStatus</td><td>Indicator / OfflineHollow</td><td>DetailWindow 头灯（bf95dde）；空心变体=胶囊离线横幅口径</td></tr><tr><td>ComponentMetric</td><td>Value</td><td>词汇件（候 Phase 3 绑定）</td></tr><tr><td>ComponentProgress</td><td>FillColor / Bar</td><td>FillColor 委托 ProgressTiers；Bar 静态条词汇件</td></tr><tr><td>ComponentKeyValue</td><td>Row</td><td>DetailWindow 详情表（1db70de）</td></tr><tr><td>ComponentList</td><td>Vertical</td><td>DetailWindow 详情表容器</td></tr><tr><td>ComponentCard</td><td>Status</td><td>词汇件（Surface.Card 组合）</td></tr><tr><td>ComponentAction</td><td>Button / Item / Menu / Link</td><td>Detail 动作区 + QuickPanel pin 右键（bb86927）；Link 词汇件</td></tr><tr><td>ComponentLayout</td><td>Row / Column / Columns / SectionLabel / When</td><td>QuickPanel 三行与空区收起、Detail 头行/动作行/区段签、PinnedHost 六列（8caf0b5）</td></tr><tr><td>ComponentFeedback</td><td>Empty / Loading / Error / Offline</td><td>词汇件（5489352）；现 UX 口径=空区隐藏+XAML 横幅</td></tr></tbody></table><h2 id="_3-未收编余量-逐面推进-不阻塞期次" tabindex="-1">3 未收编余量（逐面推进，不阻塞期次） <a class="header-anchor" href="#_3-未收编余量-逐面推进-不阻塞期次" aria-label="Permalink to &quot;3 未收编余量（逐面推进，不阻塞期次）&quot;">​</a></h2><ul><li>bespoke Thickness：chip <code>Padding(8,3,8,3)</code>、胶囊/面板 XAML 内边距——等对应面组件化时顺带。</li><li>SettingsWindow 按钮族（约 17 处 <code>new Button</code>）：表单按钮，非「动作」词汇，候表单组件化批。</li><li>XAML 面布局（QuickPanelWindow.xaml 的 Grid/Stack）：XAML 无工厂可落，维持资源镜像约束。</li></ul><h2 id="_4-证明面" tabindex="-1">4 证明面 <a class="header-anchor" href="#_4-证明面" aria-label="Permalink to &quot;4 证明面&quot;">​</a></h2><p>已采用件的证明=CI 像素断言（值等价成立即绿）。词汇件（Surface/Badge/Divider/Metric/StatusCard/ Link/Column/Feedback 四态）的证明面=Phase 2 末行<strong>独立视觉示例页</strong>（todo 分期第 9 行）与 Phase 3 绑定引擎； 无面落地是设计内的词汇表阶段，不是完成态。</p>',12)])])}const m=d(r,[["render",n]]);export{u as __pageData,m as default};
